1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots, mostRecentSlot } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, staleDispatchIssues, staleEscalationComment,
18	  rearmDispatchIssues, readyLabelOn, staleClaimedDispatchIssues, staleClaimComment,
19	  AGENT_RUNNING_LABEL,
20	} from './dispatch.mjs';
21	import { isAgentless } from './model-map.mjs';
22	import { isDormant } from '../checks/helpers/repo-context.mjs';
23	import { renderTaskRuns } from './run-record.mjs';
24	import { localSignalContext } from './signals/local.mjs';
25	import { runPreprocessing, preprocessingFailure, agentRequestPath, clearAgentRequest, agentRequested } from './preprocess.mjs';
26	
27	// The due tasks, each paired with the slot it runs under. Union the discovered
28	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
29	// frequencies back to their tasks. A task whose frequency isn't due drops out.
30	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess, forced = []) {
31	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
32	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
33	  const out = [];
34	  for (const task of tasks) {
35	    const slot = due.get(task.decl.frequency);
36	    if (slot) { out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime }); continue; }
37	    // A FORCED task runs under its most-recent slot even though that slot has
38	    // already been run. This gate is the reason forcing has to live here at all:
39	    // the due list is computed BEFORE any precondition, so a task whose slot has
40	    // passed is never looked at again — and a mid-day forced run is the only kind
41	    // that matters (#515). `planRun` then skips its precondition outright.
42	    if (forced.includes(task.id)) {
43	      const s = mostRecentSlot(task.decl.frequency, schedule, now);
44	      out.push({ task, slotId: s.id, slotTime: s.time, forced: true });
45	    }
46	  }
47	  return out;
48	}
49	
50	// The verdict a forced task gets INSTEAD of its precondition. The context line
51	// is generic on purpose — it names the mechanism, not the task — and it is there
52	// because a dispatch issue's Context is the agent's binding scope: a forced
53	// dispatch that carried none would read as a scope of nothing, and the agent
54	// should know it arrived by a hand-started run rather than a met condition.
55	const FORCED_VERDICT = Object.freeze({
56	  run: true,
57	  reason: 'forced by FORCE_TASKS on a manual scheduler run — its precondition was not evaluated',
58	  context: Object.freeze(['This run was forced manually (FORCE_TASKS on a workflow_dispatch); the task\'s own precondition was not evaluated, so nothing here asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.']),
59	});
60	
61	// The task ids a manual run forced, out of the opaque override bag. This is the
62	// ONE key the engine reads from that bag, and it is deliberately generic: it
63	// learns "run these task ids", never what any of them do. No task declaration
64	// mentions forcing, and no precondition is consulted for a forced task — an id
65	// matching no discovered task simply forces nothing.
66	export function forcedTaskIds(overrides = {}) {
67	  return String(overrides.FORCE_TASKS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
68	}
69	
70	// The union of signal names the due tasks declare — the scheduler collects only
71	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
72	export function signalsUnion(dueTaskSlots) {
73	  const names = new Set();
74	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
75	  return [...names];
76	}
77	
78	// The signal-collection lookback: the widest due task's period plus 1h slack
79	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
80	const FREQUENCY_MS = {
81	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
82	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
83	};
84	export function windowStart(dueTaskSlots, now) {
85	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
86	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
87	}
88	
89	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
90	// precondition converges to a skip with the error recorded — it never sinks the
91	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
92	// issue separately.
93	export function runPrecondition(task, signals, packConfig) {
94	  try {
95	    const v = task.decl.precondition(signals, packConfig) ?? {};
96	    return {
97	      run: v.run === true,
98	      reason: v.reason ?? '',
99	      context: Array.isArray(v.context) ? v.context : [],
100	    };
101	  } catch (e) {
102	    return { run: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
103	  }
104	}
105	
106	// A human-readable job-summary line per evaluated task — the observability the
107	// old plan.json gave (DESIGN §3.6).
108	export function renderSummary(evaluations) {
109	  return evaluations.map((e) => {
110	    const verb = !e.run ? 'skip' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
111	    const forced = e.forced ? ' (forced)' : '';
112	    return `- ${e.pack}/${e.task} [${e.slotId}]${forced} ${verb} — ${e.reason || e.dispatch?.reason || ''}`.trimEnd();
113	  }).join('\n');
114	}
115	
116	// Orchestrate one scheduler run into a set of decisions — the reusable core the
117	// CLI wraps with real GitHub I/O. Injected seams:
118	//   collectSignals(names) -> signals object (the declared union, collected once)
119	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
120	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state}]
121	// Returns `{ evaluations }`: one record per due task with its precondition
122	// verdict and, when it runs, either an inline marker (agent_model: none) or a
123	// dispatch decision (planDispatch).
124	//
125	// DORMANCY IS THE FIRST GATE, ahead of the due-slot math and every task's own
126	// precondition (`config`, the repo's loaded declaration). A dormant project has
127	// said it is out of the recurring work: it is not that each task happens to have
128	// nothing to do, it is that no task is asked. Putting the gate here rather than
129	// in each precondition is the whole point — every task, canon and local, present
130	// and future, is covered by one decision nothing has to opt into, and a task
131	// never learns that dormancy exists.
132	export async function planRun({
133	  tasks, schedule, now, lastSuccess, overrides = {}, config = {},
134	  collectSignals, packConfigFor = () => ({}), existingIssuesFor = async () => [],
135	}) {
136	  if (isDormant(config)) return { evaluations: [], dormant: true };
137	  // `overrides` arrives as a parameter rather than out of `signals` because the
138	  // due list is what decides which signals get collected — the bag has to be
139	  // known before the collection it would otherwise be part of.
140	  const dueList = computeDueTaskSlots(tasks, schedule, now, lastSuccess, forcedTaskIds(overrides));
141	  const signals = await collectSignals(signalsUnion(dueList));
142	
143	  const evaluations = [];
144	  for (const { task, slotId, forced } of dueList) {
145	    // A FORCED task does not consult its precondition at all. "Forced" is a
146	    // decision the operator already made, so asking the task whether it agrees is
147	    // both redundant and a way for the answer to be no — and a task that could
148	    // veto a force would need to know forcing exists, which is exactly the
149	    // coupling this mechanism avoids. Nothing in a task declaration mentions
150	    // forcing; the engine owns it end to end.
151	    const pre = forced ? FORCED_VERDICT : runPrecondition(task, signals, packConfigFor(task.pack));
152	    const rec = {
153	      pack: task.pack, task: task.id, slotId,
154	      model: task.decl.agent_model, outcome: task.decl.expected_outcome,
155	      run: pre.run, reason: pre.reason, context: pre.context,
156	    };
157	    if (forced) rec.forced = true;
158	    if (pre.error) rec.error = pre.error;
159	    if (pre.run) {
160	      // A declared agent_preprocessing runs as a subprocess BEFORE any agent
161	      // (DESIGN §3) — flagged here (pure) for the summary; the CLI shell executes
162	      // it. An agentless task is preprocessing-only; an agentful one hands off to
163	      // the agent after preprocessing succeeds.
164	      if (task.decl.agent_preprocessing) rec.preprocessing = true;
165	      if (isAgentless(task.decl.agent_model)) {
166	        // agent_model: none — no agent and no dispatch issue on success. A task with
167	        // no preprocessing runs the legacy inline worker; with preprocessing it is
168	        // the subprocess above.
169	        rec.inline = true;
170	      } else {
171	        const existing = await existingIssuesFor(task.pack, task.id);
172	        // Route the dispatch to the self or fleet ready label by the task's scope
173	        // (the fleet/self executor split) — the executor routine wired to that
174	        // label runs it.
175	        const readyLabel = readyLabelForScope(task.decl.session_scope);
176	        rec.dispatch = planDispatch({ existing, pack: task.pack, task: task.id, slotId, readyLabel });
177	      }
178	    }
179	    evaluations.push(rec);
180	  }
181	  return { evaluations };
182	}
183	
184	// The opaque override bag a MANUAL run may carry (`workflow_dispatch` input →
185	// `CLAUDINITE_OVERRIDES`). GitHub cannot declare arbitrary named inputs, so the
186	// workflow takes ONE free-form string and this splits it into keys.
187	//
188	// Exactly one key is understood: `FORCE_TASKS` (see `forcedTaskIds`), and it is
189	// understood GENERICALLY — "run these task ids", never what any of them do. No
190	// task declaration mentions forcing and no precondition is consulted for a forced
191	// task, so the scheduler never learns what baselining is and baselining never
192	// learns that forcing exists. Anything else in the bag is parsed and ignored,
193	// which is what leaves room for a future override without a schema.
194	//
195	// `A=1,B=2`, newline-separated, or bare `A` (⇒ `'true'`). Values stay STRINGS with
196	// no truthiness coercion: a task compares against the literal it documents, so
197	// `FORCE_X=false` can never read as "the key is present, therefore on".
198	export function parseOverrides(raw) {
199	  const out = {};
200	  for (const part of String(raw ?? '').split(/[,\n]/)) {
201	    const token = part.trim();
202	    if (!token) continue;
203	    const eq = token.indexOf('=');
204	    if (eq === -1) out[token] = 'true';
205	    else out[token.slice(0, eq).trim()] = token.slice(eq + 1).trim();
206	  }
207	  return out;
208	}
209	
210	// The `ctx` every signal collector reads (DESIGN §3.3) — the already-resolved
211	// facts a collector may not go and fetch for itself, built once per run and
212	// handed to `collectSignals`. Exported so the construction itself is testable:
213	// the collectors' `ctx.X ?? null` seam makes them unit-testable with a hand-built
214	// ctx, which is exactly why a key nothing here populates can read as "collector
215	// works" forever. Assert against THIS, not a hand-built shape.
216	// `root` is the Action-side checkout: the manifest version, the local-pack
217	// presence and the configured retention are all read from it (signals/local.mjs),
218	// because a scheduled run already has the tree on disk and an API round-trip
219	// would buy nothing.
220	export function buildSignalContext({ root, repo, defaultBranch, now, sinceIso, config, fleet = null, packConfigFor = () => ({}) }) {
221	  const local = localSignalContext(root, { packIds: config.packs ?? [], packConfigFor });
222	  return {
223	    repo, defaultBranch, now, sinceIso, config,
224	    activePacks: config.packs, fleet,
225	    manifestVersion: local.manifestVersion,
226	    hasLocalPacks: local.hasLocalPacks,
227	    retentionDays: local.retentionDays,
228	  };
229	}
230	
231	// --- CLI: the thin I/O shell the vendored workflow invokes -------------------
232	// Wires the run-ledger read, signal collectors, and issue I/O around planRun,
233	// then acts on each decision (file a labeled dispatch issue, or run an inline
234	// worker) and prints the job summary. All GitHub access here is the Action's
235	// GITHUB_TOKEN — the one sanctioned non-MCP surface (DESIGN §10).
236	
237	// The task family's issues (state=all) via the search API, filtered to exact
238	// prefix — the input planDispatch's exactly-once / at-most-one-open guards read.
239	async function existingIssuesViaSearch(gh, repo, pack, task) {
240	  const q = encodeURIComponent(`repo:${repo} in:title "${DISPATCH_PREFIX} ${pack}/${task}"`);
241	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
242	  if (status !== 200 || !Array.isArray(json?.items)) return [];
243	  const prefix = `${DISPATCH_PREFIX} ${pack}/${task} `;
244	  return json.items
245	    .filter((i) => `${(i.title ?? '').trim()} `.startsWith(prefix))
246	    .map((i) => ({ number: i.number, title: i.title, state: i.state }));
247	}
248	
249	// Every OPEN dispatch issue in the repo, with the labels / age / comment count the
250	// maintenance pass reads. Separate from existingIssuesViaSearch, which is per task
251	// family and state=all for the filing guards; this one is repo-wide and open-only.
252	export async function openDispatchIssuesViaSearch(gh, repo) {
253	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${DISPATCH_PREFIX}"`);
254	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
255	  if (status !== 200 || !Array.isArray(json?.items)) return [];
256	  return json.items.map((i) => ({
257	    number: i.number, title: i.title, labels: i.labels ?? [],
258	    created_at: i.created_at, updated_at: i.updated_at, comments: i.comments ?? 0,
259	  }));
260	}
261	
262	// The per-run maintenance pass over open dispatch issues (DESIGN §4 lifecycle,
263	// §5 recovery). Three backstops, in this order:
264	//   1. STALE — open past ~2 of its own scheduling periods → escalation comment,
265	//      drop the ready label (so it stops being armed), add `needs-human`.
266	//   2. DEAD CLAIM — `agent-running` with no activity for ~3h → the session that
267	//      claimed it died; comment, drop `agent-running`, add `needs-human`.
268	//   3. RE-ARM — armed but untouched past the grace window → the trigger event was
269	//      lost, so remove and re-add its ready label to emit a fresh one.
270	// Stale wins over re-arm: rearmDispatchIssues already excludes the stale set, so an
271	// issue converging to triage is never re-armed back into circulation.
272	//
273	// This is the ONLY recovery path for a missed label event or a dead session. The
274	// executor no longer sweeps other issues — one session runs exactly the one issue
275	// that triggered it — so recovery had to become a decision in code here, running
276	// once per scheduler run, rather than agent judgment replicated across every
277	// concurrently-triggered session.
278	export async function maintainDispatchIssues(gh, repo, now, { labelsEnsured = false } = {}) {
279	  const open = await openDispatchIssuesViaSearch(gh, repo);
280	  const none = { stale: [], deadClaims: [], rearmed: [] };
281	  if (!open.length) return none;
282	
283	  const stale = staleDispatchIssues(open, now);
284	  const staleNumbers = new Set(stale.map((i) => i.number));
285	  const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));
286	  const rearm = rearmDispatchIssues(open, now);
287	  if (!stale.length && !deadClaims.length && !rearm.length) return none;
288	
289	  // Applying a label 422s when it does not exist, so guarantee them first — an
290	  // idle run never gets here, so this costs nothing on the common path.
291	  if (!labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
292	
293	  const escalate = async (issue, body, dropLabel) => {
294	    await gh(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body } });
295	    if (dropLabel) await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(dropLabel)}`, { method: 'DELETE' });
296	    await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [NEEDS_HUMAN_LABEL] } });
297	  };
298	
299	  for (const issue of stale) {
300	    await escalate(issue, staleEscalationComment(issue), readyLabelOn(issue));
301	    console.log(`- escalated stale dispatch #${issue.number} to ${NEEDS_HUMAN_LABEL}`);
302	  }
303	
304	  for (const issue of deadClaims) {
305	    await escalate(issue, staleClaimComment(issue), AGENT_RUNNING_LABEL);
306	    console.log(`- reclaimed dead ${AGENT_RUNNING_LABEL} claim on #${issue.number} → ${NEEDS_HUMAN_LABEL}`);
307	  }
308	
309	  for (const issue of rearm) {
310	    const ready = readyLabelOn(issue);
311	    const del = await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(ready)}`, { method: 'DELETE' });
312	    if (del.status >= 300) { console.log(`! could not un-label #${issue.number} to re-arm it: ${del.status}`); continue; }
313	    const add = await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [ready] } });
314	    if (add.status >= 300) console.log(`! re-arm of #${issue.number} dropped its ${ready} label: ${add.status}`);
315	    else console.log(`- re-armed #${issue.number} (${ready}) — its trigger event never landed`);
316	  }
317	
318	  return {
319	    stale: stale.map((i) => i.number),
320	    deadClaims: deadClaims.map((i) => i.number),
321	    rearmed: rearm.map((i) => i.number),
322	  };
323	}
324	
325	// Ensure the dispatch labels exist before any is applied — GitHub 422s when you
326	// apply an unknown label (it never creates one on demand), so the scheduler, as the
327	// thing that assigns them, guarantees them here. Idempotent (201 created / 422 already
328	// exists are both success) and self-healing (a deleted label reappears next run), which
329	// is why no separate one-off label-creation step is needed. Exported for the run tests.
330	export async function ensureLabels(gh, repo, labels) {
331	  for (const { name, color, description } of labels) {
332	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
333	    if (res.status === 201) continue;                       // created to spec — nothing further
334	    if (res.status === 422) {
335	      // The NAME is taken; that says nothing about the colour or description. A
336	      // label GitHub auto-created (applying an unknown name to an issue mints it
337	      // grey `ededed`, no description) would keep those defaults for good, because
338	      // POST 422s forever. So reconcile the shape, not just the existence — that
339	      // is what makes the self-healing claim above true for drift and not only for
340	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
341	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
342	        method: 'PATCH', body: { color, description },
343	      });
344	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
345	      continue;
346	    }
347	    console.log(`! could not ensure label "${name}": ${res.status}`);
348	  }
349	}
350	
351	async function main() {
352	  const { makeGh, lastSuccessTime, actionRepoContext } = await import('./signals/gh.mjs');
353	  const { collectSignals } = await import('./signals/index.mjs');
354	  const { discoverTasks } = await import('./discover.mjs');
355	  const { loadConfig } = await import('../checks/helpers/repo-context.mjs');
356	
357	  const root = process.cwd();
358	  const { repo, defaultBranch } = actionRepoContext();
359	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
360	  const gh = makeGh();
361	  const config = loadConfig(root);
362	
363	  // The dormancy gate, before ANY of it: the run-ledger read, the task discovery,
364	  // the signal collection, the issue I/O, the dispatch maintenance. planRun holds
365	  // the same verdict (one predicate, both call sites) and would return an empty
366	  // plan — but a dormant repo should not pay for the reads that produce it, and
367	  // the maintenance pass below writes to issues, which is exactly the ceremony
368	  // dormancy exists to stop.
369	  //
370	  // Exit 0, deliberately. The run enters the success ledger and the watermark
371	  // advances past these slots, so waking a project up does NOT replay the months
372	  // it slept through — it simply starts scheduling again from now. Slots skipped
373	  // while dormant are skipped on purpose, not deferred.
374	  if (isDormant(config)) {
375	    console.log('## Claudinite scheduler\n');
376	    console.log('- this project declares itself dormant ("dormant": true in .claudinite-checks.json) — no tasks evaluated, no work dispatched');
377	    return;
378	  }
379	
380	  const { tasks, errors } = await discoverTasks(root, config);
381	  for (const e of errors) console.log(`! ${e.what}`);
382	
383	  const now = new Date();
384	  // The watermark IS the scheduler's state, so a run that cannot read it cannot
385	  // compute due-ness at all — and every guess is wrong in a way nobody sees:
386	  // "assume fresh" re-fires the first-run set on a mature repo, "assume now"
387	  // silently eats the slots it skipped. Fail the run instead. It must exit
388	  // NON-ZERO: an exit-0 abort would enter the success ledger and advance the
389	  // watermark past the very slots it declined to evaluate. Failing leaves the
390	  // watermark untouched, so the next successful run catches them up (#522).
391	  let lastSuccess;
392	  try {
393	    lastSuccess = await lastSuccessTime(gh, repo);
394	  } catch (e) {
395	    console.error(`${e.message} — cannot compute due slots; failing this run so the next one catches up`);
396	    process.exit(1);
397	  }
398	  const schedule = config.taskScheduler;
399	
400	  const due = computeDueTaskSlots(tasks, schedule, now, lastSuccess);
401	  const sinceIso = windowStart(due, now);
402	
403	  // The fleet aggregate (canon-only, DESIGN §3.3) is expensive — a full
404	  // enumeration over the fleet PAT — so build it ONLY when a due task actually
405	  // declares the `fleet` signal, and only when FLEET_GITHUB_TOKEN is set (the
406	  // canon repo with the census credential). Otherwise ctx.fleet stays null and
407	  // the collector returns null, so a fleet task's precondition skips rather than
408	  // crashes. Enumeration failures are surfaced by readFleet as `{ error }`, not
409	  // thrown — a fleet task treats that as "no work I can prove".
410	  let fleet = null;
411	  if (signalsUnion(due).includes('fleet')) {
412	    const { readFleet, makeFleetGh } = await import('./signals/fleet.mjs');
413	    const fleetGh = makeFleetGh();
414	    if (fleetGh) {
415	      const owner = repo.split('/')[0];
416	      fleet = await readFleet(fleetGh, { owner, canonRepo: repo, sinceIso });
417	      if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
418	    } else {
419	      console.log('- a due task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set — skipping fleet-scoped tasks');
420	    }
421	  }
422	
423	  const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
424	
425	  // An override only ever arrives on a hand-started run, and it makes a task run
426	  // that its own precondition would have skipped — so say so in the log. An
427	  // unattended system that can be forced silently is one whose run history stops
428	  // explaining itself.
429	  const overrides = parseOverrides(process.env.CLAUDINITE_OVERRIDES);
430	  const overrideKeys = Object.keys(overrides);
431	  if (overrideKeys.length > 0) {
432	    console.log(`- manual run overrides: ${overrideKeys.map((k) => `${k}=${overrides[k]}`).join(', ')}`);
433	  }
434	
435	  const ctx = buildSignalContext({
436	    root, repo, defaultBranch, now: now.toISOString(), sinceIso, config, fleet, packConfigFor,
437	  });
438	
439	  const { evaluations } = await planRun({
440	    tasks, schedule, now, lastSuccess, overrides, config,
441	    collectSignals: (names) => collectSignals(gh, ctx, names),
442	    packConfigFor,
443	    existingIssuesFor: (pack, task) => existingIssuesViaSearch(gh, repo, pack, task),
444	  });
445	
446	  // Guarantee the dispatch labels exist before we file any labeled issue — when a
447	  // task will dispatch OR will run preprocessing (which may converge to
448	  // needs-human). An idle run pays nothing.
449	  const labelsEnsured = evaluations.some((r) => r.run && (r.preprocessing || (!r.inline && r.dispatch?.action === 'create')));
450	  if (labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
451	
452	  // File the labeled hand-off issue the executor runs (READY_LABEL): first line is
453	  // the task path, body carries the precondition's binding Context (dispatch.mjs).
454	  const fileHandoff = async (rec, taskObj) => {
455	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
456	    const body = dispatchBody({ taskPath: taskObj.taskPath, pack: rec.pack, task: rec.task, slotId: rec.slotId, context: rec.context });
457	    // The scope-resolved ready label (self vs fleet) from planDispatch — the
458	    // executor routine wired to it runs the task.
459	    const readyLabel = rec.dispatch?.label ?? READY_LABEL;
460	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: [readyLabel] } });
461	    if (res.status >= 300) console.log(`! failed to file dispatch issue for ${rec.pack}/${rec.task}: ${res.status}`);
462	  };
463	
464	  // Converge a failed preprocessing run to a single open needs-human issue for the
465	  // family — at-most-one-open, so a repeatedly-failing task never spams issues.
466	  const fileNeedsHuman = async (rec, why, extra) => {
467	    const existing = await existingIssuesViaSearch(gh, repo, rec.pack, rec.task);
468	    if (existing.some((i) => i.state === 'open')) {
469	      console.log(`  (an open dispatch issue already covers ${rec.pack}/${rec.task} — not filing another)`);
470	      return;
471	    }
472	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
473	    const body = [
474	      `Preprocessing for \`${rec.pack}/${rec.task}\` (slot \`${rec.slotId}\`) failed and needs human triage.`,
475	      '', `- ${why}`, ...extra.map((e) => `- ${e}`),
476	    ].join('\n') + '\n';
477	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: [NEEDS_HUMAN_LABEL] } });
478	    if (res.status >= 300) console.log(`! failed to file needs-human issue for ${rec.pack}/${rec.task}: ${res.status}`);
479	  };
480	
481	  for (const rec of evaluations) {
482	    if (!rec.run) continue;
483	    const taskObj = tasks.find((t) => t.pack === rec.pack && t.id === rec.task);
484	    const decl = taskObj.decl;
485	
486	    // Stage 1 — preprocessing (DESIGN §3): run the declared command as a subprocess
487	    // bounded by its timeout, before any agent. Its cwd is the task dir; the repo
488	    // root + slot context ride in via CLAUDINITE_* env.
489	    if (rec.preprocessing) {
490	      // A per-run signal path the worker writes to REQUEST the agent stage
491	      // (conditional handoff, §3). Clear any stale one first so a prior run can't
492	      // spuriously escalate this one.
493	      const requestPath = agentRequestPath(rec);
494	      clearAgentRequest(requestPath);
495	      const result = await runPreprocessing(decl.agent_preprocessing, {
496	        taskDir: taskObj.taskDir,
497	        env: {
498	          ...process.env,
499	          CLAUDINITE_REPO_ROOT: root,
500	          CLAUDINITE_REPO: repo,
501	          CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
502	          CLAUDINITE_SLOT_ID: rec.slotId,
503	          CLAUDINITE_PACK: rec.pack,
504	          CLAUDINITE_TASK: rec.task,
505	          CLAUDINITE_REQUEST_AGENT: requestPath,
506	        },
507	        timeoutSeconds: decl.agent_preprocessing_timeout,
508	      });
509	      rec.preprocessResult = { ok: result.ok, timedOut: result.timedOut, code: result.code };
510	      if (!result.ok) {
511	        const why = preprocessingFailure(result);
512	        console.log(`! preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ${why}`);
513	        const extra = result.stderr?.trim() ? [`stderr tail: ${result.stderr.trim().split('\n').slice(-3).join(' / ')}`] : [];
514	        await fileNeedsHuman(rec, why, extra);
515	        clearAgentRequest(requestPath);
516	        continue; // never hand off to an agent after a failed preprocessing
517	      }
518	      // Success. An agentless task is done (no issue on success, as the old inline
519	      // was quiet). An agentful one hands off ONLY when the worker requested the
520	      // agent (conditional escalation, §3): a task that absorbs its work into
521	      // preprocessing stays quiet on the nights nothing needs judgment.
522	      const requested = agentRequested(requestPath);
523	      clearAgentRequest(requestPath);
524	      rec.agentRequested = requested;
525	      console.log(`preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ok${rec.inline ? '' : requested ? ' (agent requested)' : ' (no agent needed)'}`);
526	      if (rec.inline) continue;
527	      if (requested && rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
528	      continue;
529	    }
530	
531	    // No preprocessing. An agentless task with no preprocessing does nothing — the
532	    // contract now forbids it (agent_model:none REQUIRES agent_preprocessing, so
533	    // the in-process inline worker path is retired, DESIGN §4). Defensive no-op
534	    // should one slip past validation.
535	    if (rec.inline) {
536	      console.log(`- ${rec.pack}/${rec.task}: agentless with no preprocessing — nothing to run (contract-forbidden)`);
537	      continue;
538	    }
539	    // Agent task with no preprocessing → today's immediate labeled dispatch.
540	    if (rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
541	  }
542	
543	  // Maintenance over the open dispatch issues, AFTER this run's filings: the
544	  // issues just filed are seconds old, so the grace window keeps them out of the
545	  // re-arm set and only the previous cycles' leftovers are considered.
546	  await maintainDispatchIssues(gh, repo, now, { labelsEnsured });
547	
548	  console.log('## Claudinite scheduler\n');
549	  console.log(renderSummary(evaluations) || '- no tasks due');
550	
551	  // The machine-readable half of the same story (run-record.mjs): one line per due
552	  // task saying what this run DID with it — dispatched an agent, ran it as
553	  // preprocessing only, skipped it on its precondition, failed it, or deferred it.
554	  // Printed AFTER the action loop, so each line reports what happened rather than
555	  // what was planned, and read back by the usage fold to count task invocations.
556	  // Nothing else in the scheduler depends on it: this is a record, not a signal.
557	  if (evaluations.length) console.log(`\n${renderTaskRuns(evaluations)}`);
558	}
559	
560	// Run only when invoked directly (the workflow's `node run.mjs`), never on import.
561	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
562	  main().catch((e) => { console.error(e); process.exit(1); });
563	}
564

